code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    observed = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in observed and observed[d] != value:
                    raise ValueError("inconsistent diagonal")
                observed[d] = value
    if not observed:
        return [row[:] for row in grid]
    period = next(p for p in range(1, h + w + 1)
                  if all(all((d - e) % p != 0 or value == other
                             for e, other in observed.items())
                         for d, value in observed.items()))
    pattern = {}
    for d, value in observed.items():
        pattern[d % period] = value
    for residue in range(period):
        if residue not in pattern:
            reflected = (-residue) % period
            if reflected in pattern:
                pattern[residue] = pattern[reflected]
            else:
                nearest = min(pattern, key=lambda x: min((residue-x) % period, (x-residue) % period))
                pattern[residue] = pattern[nearest]
    return [[pattern[(c-r) % period] for c in range(w)] for r in range(h)]
'''
